-- Airline Delay Analysis: analytical queries (SQLite dialect)
-- Tables: airports, carriers, flights (all SYNTHETIC data generated by this project)
-- is_delayed = 1 means arrival delay of 15 minutes or more, so AVG(is_delayed) is the delay rate.
-- Note: statements are separated by a semicolon, so comments must not contain one.

-- Q1: What is the delay rate, flight count and mean arrival delay for each origin airport, with city and region?
SELECT
    a.airport_code,
    a.city,
    a.region,
    COUNT(*)                            AS flights,
    ROUND(AVG(f.is_delayed), 3)         AS delay_rate,
    ROUND(AVG(f.arr_delay_min), 1)      AS mean_arr_delay_min
FROM flights AS f
JOIN airports AS a ON a.airport_code = f.origin
GROUP BY a.airport_code, a.city, a.region
ORDER BY delay_rate DESC;

-- Q2: How do carriers rank by delay rate, and what are their names and business types?
SELECT
    RANK() OVER (ORDER BY AVG(f.is_delayed) DESC) AS delay_rank,
    c.carrier_code,
    c.carrier_name,
    c.carrier_type,
    COUNT(*)                            AS flights,
    ROUND(AVG(f.is_delayed), 3)         AS delay_rate,
    ROUND(AVG(f.dep_delay_min), 1)      AS mean_dep_delay_min
FROM flights AS f
JOIN carriers AS c ON c.carrier_code = f.carrier_code
GROUP BY c.carrier_code, c.carrier_name, c.carrier_type
ORDER BY delay_rank;

-- Q3: What is the hourly profile of delays by scheduled departure hour?
SELECT
    scheduled_dep_hour,
    COUNT(*)                            AS flights,
    ROUND(AVG(is_delayed), 3)           AS delay_rate,
    ROUND(AVG(arr_delay_min), 1)        AS mean_arr_delay_min
FROM flights
GROUP BY scheduled_dep_hour
ORDER BY scheduled_dep_hour;

-- Q4: How does the delay rate differ by business type of carrier and by time of day (morning, afternoon, evening)?
SELECT
    c.carrier_type,
    CASE
        WHEN f.scheduled_dep_hour < 12 THEN '1 morning (before 12)'
        WHEN f.scheduled_dep_hour < 17 THEN '2 afternoon (12-16)'
        ELSE '3 evening (17+)'
    END                                 AS day_part,
    COUNT(*)                            AS flights,
    ROUND(AVG(f.is_delayed), 3)         AS delay_rate
FROM flights AS f
JOIN carriers AS c ON c.carrier_code = f.carrier_code
GROUP BY c.carrier_type, day_part
ORDER BY c.carrier_type, day_part;

-- Q5: How does the delay rate change across weather severity bands?
SELECT
    CASE
        WHEN weather_severity < 1 THEN '0-1 calm'
        WHEN weather_severity < 2 THEN '1-2 light'
        WHEN weather_severity < 4 THEN '2-4 moderate'
        ELSE '4+ severe'
    END                                 AS weather_band,
    COUNT(*)                            AS flights,
    ROUND(AVG(is_delayed), 3)           AS delay_rate,
    ROUND(AVG(dep_delay_min), 1)        AS mean_dep_delay_min
FROM flights
GROUP BY weather_band
ORDER BY weather_band;

-- Q6: Which months have the highest delay rate, and how does each compare with the overall rate?
WITH overall AS (
    SELECT AVG(is_delayed) AS overall_rate FROM flights
)
SELECT
    f.month,
    COUNT(*)                                            AS flights,
    ROUND(AVG(f.is_delayed), 3)                         AS delay_rate,
    ROUND(AVG(f.is_delayed) - o.overall_rate, 3)        AS diff_vs_overall
FROM flights AS f
CROSS JOIN overall AS o
GROUP BY f.month, o.overall_rate
ORDER BY delay_rate DESC;

-- Q7: Which airport and carrier combinations (at least 30 flights) have the highest delay rate?
SELECT
    f.origin,
    f.carrier_code,
    c.carrier_name,
    COUNT(*)                            AS flights,
    ROUND(AVG(f.is_delayed), 3)         AS delay_rate
FROM flights AS f
JOIN carriers AS c ON c.carrier_code = f.carrier_code
GROUP BY f.origin, f.carrier_code, c.carrier_name
HAVING COUNT(*) >= 30
ORDER BY delay_rate DESC, flights DESC
LIMIT 10;

-- Q8: Which routes (at least 15 flights) have the highest mean arrival delay, with origin and destination cities?
SELECT
    f.origin || ' -> ' || f.destination AS route,
    ao.city                             AS origin_city,
    ad.city                             AS destination_city,
    COUNT(*)                            AS flights,
    ROUND(AVG(f.is_delayed), 3)         AS delay_rate,
    ROUND(AVG(f.arr_delay_min), 1)      AS mean_arr_delay_min
FROM flights AS f
JOIN airports AS ao ON ao.airport_code = f.origin
JOIN airports AS ad ON ad.airport_code = f.destination
GROUP BY f.origin, f.destination, ao.city, ad.city
HAVING COUNT(*) >= 15
ORDER BY mean_arr_delay_min DESC
LIMIT 10;
